package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity @Table(name="inventory_adjustment") public class AjusteInventario{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;
 @Column(name="adjustment_number",nullable=false,updatable=false,length=30)private String numero;@Column(name="effective_date",nullable=false)private LocalDate fecha;@Column(name="warehouse_id",nullable=false)private UUID almacenId;@Column(name="reason_id",nullable=false)private UUID motivoId;
 @Column(name="reference",length=100)private String referencia;@Column(name="notes",length=1000)private String observacion;@Enumerated(EnumType.STRING)@Column(name="adjustment_type",nullable=false,length=10)private TipoAjusteInventario tipo;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private EstadoAjusteInventario status;
 @Column(name="warehouse_name_snapshot",length=200)private String almacenHistorico;@Column(name="branch_name_snapshot",length=200)private String sucursalHistorica;@Column(name="reason_name_snapshot",length=150)private String motivoHistorico;
 @Column(name="confirmed_at")private OffsetDateTime confirmadaEn;@Column(name="confirmed_by")private UUID confirmadaPor;@Column(name="confirmed_by_name_snapshot",length=200)private String confirmadaPorNombre;
 @Column(name="cancelled_at")private OffsetDateTime anuladaEn;@Column(name="cancelled_by")private UUID anuladaPor;@Column(name="cancellation_reason",length=500)private String motivoAnulacion;
 @Column(name="reversed_at")private OffsetDateTime revertidaEn;@Column(name="reversed_by")private UUID revertidaPor;@Column(name="reversed_by_adjustment_id")private UUID revertidaPorAjusteId;@Column(name="reversal_of_id")private UUID reversoDeId;
 @Column(name="created_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime creadaEn;@Column(name="created_by",nullable=false,updatable=false)private UUID creadaPor;@Column(name="updated_at",nullable=false,insertable=false)private OffsetDateTime actualizadaEn;@Column(name="updated_by",nullable=false)private UUID actualizadaPor;@Version private long version;
 @ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="warehouse_id",insertable=false,updatable=false)private Almacen almacen;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="reason_id",insertable=false,updatable=false)private MotivoAjusteInventario motivo;
 protected AjusteInventario(){}
 public AjusteInventario(UUID t,UUID e,String n,LocalDate f,Almacen a,MotivoAjusteInventario m,String r,String o,TipoAjusteInventario tipo,UUID u){tenantId=t;empresaId=e;numero=n;fecha=f;almacenId=a.getId();motivoId=m.getId();referencia=r;observacion=o;this.tipo=tipo;status=EstadoAjusteInventario.DRAFT;creadaPor=u;actualizadaPor=u;almacen=a;motivo=m;}
 public void actualizar(LocalDate f,Almacen a,MotivoAjusteInventario m,String r,String o,TipoAjusteInventario tipo,UUID u){exigirBorrador();fecha=f;almacenId=a.getId();motivoId=m.getId();referencia=r;observacion=o;this.tipo=tipo;actualizadaPor=u;almacen=a;motivo=m;}
 public void confirmar(UUID u,String nombre){exigirBorrador();status=EstadoAjusteInventario.CONFIRMED;confirmadaEn=OffsetDateTime.now();confirmadaPor=u;confirmadaPorNombre=nombre;almacenHistorico=almacen.getNombre();sucursalHistorica=almacen.getSucursal().getNombre();motivoHistorico=motivo.getNombre();actualizadaPor=u;}
 public void anular(String razon,UUID u){exigirBorrador();status=EstadoAjusteInventario.CANCELLED;anuladaEn=OffsetDateTime.now();anuladaPor=u;motivoAnulacion=razon;actualizadaPor=u;}
 public void marcarRevertido(AjusteInventario reverso,UUID u){if(status!=EstadoAjusteInventario.CONFIRMED)throw new IllegalStateException("Solo se puede revertir un ajuste confirmado.");status=EstadoAjusteInventario.REVERSED;revertidaEn=OffsetDateTime.now();revertidaPor=u;revertidaPorAjusteId=reverso.id;actualizadaPor=u;}
 public void establecerReversoDe(UUID original){reversoDeId=original;}private void exigirBorrador(){if(status!=EstadoAjusteInventario.DRAFT)throw new IllegalStateException("Solo se puede modificar un ajuste en borrador.");}@PreUpdate void marca(){actualizadaEn=OffsetDateTime.now();}
 public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getEmpresaId(){return empresaId;}public String getNumero(){return numero;}public LocalDate getFecha(){return fecha;}public UUID getAlmacenId(){return almacenId;}public UUID getMotivoId(){return motivoId;}public String getReferencia(){return referencia;}public String getObservacion(){return observacion;}public TipoAjusteInventario getTipo(){return tipo;}public EstadoAjusteInventario getEstado(){return status;}public String getAlmacenHistorico(){return almacenHistorico;}public String getSucursalHistorica(){return sucursalHistorica;}public String getMotivoHistorico(){return motivoHistorico;}public OffsetDateTime getConfirmadaEn(){return confirmadaEn;}public UUID getConfirmadaPor(){return confirmadaPor;}public String getConfirmadaPorNombre(){return confirmadaPorNombre;}public OffsetDateTime getAnuladaEn(){return anuladaEn;}public String getMotivoAnulacion(){return motivoAnulacion;}public OffsetDateTime getRevertidaEn(){return revertidaEn;}public UUID getRevertidaPorAjusteId(){return revertidaPorAjusteId;}public UUID getReversoDeId(){return reversoDeId;}public OffsetDateTime getCreadaEn(){return creadaEn;}public UUID getCreadaPor(){return creadaPor;}public long getVersion(){return version;}public Almacen getAlmacen(){return almacen;}public MotivoAjusteInventario getMotivo(){return motivo;}
}
